#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ll rate, duration; int n;
    if (scanf("%lld %lld %d", &rate, &duration, &n) != 3) return 0;
    vector<int> keys(n);
    for (auto &x : keys) scanf("%d", &x);
    int limit = *max_element(keys.begin(), keys.end());
    vector<ll> freq(limit + 1, 0);
    for (int x : keys) freq[x]++;
    // Divisibility of a key = sum of freq[d] over its divisors d > 1.
    ll best = 0;
    for (int v : keys) {
        ll degree = 0;
        for (int d = 1; (ll)d * d <= v; d++) {
            if (v % d) continue;
            if (d > 1) degree += freq[d];
            if (v / d != d && v / d > 1) degree += freq[v / d];
        }
        best = max(best, degree);
    }
    ll strength = best * 100000;
    printf("%d %lld\n", rate * duration >= strength ? 1 : 0, strength);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); long rate = (long) st.nval;
        st.nextToken(); long duration = (long) st.nval;
        st.nextToken(); int n = (int) st.nval;
        int[] keys = new int[n];
        int limit = 0;
        for (int i = 0; i < n; i++) { st.nextToken(); keys[i] = (int) st.nval; limit = Math.max(limit, keys[i]); }
        long[] freq = new long[limit + 1];
        for (int x : keys) freq[x]++;
        // Divisibility of a key = sum of freq[d] over its divisors d > 1.
        long best = 0;
        for (int v : keys) {
            long degree = 0;
            for (int d = 1; (long) d * d <= v; d++) {
                if (v % d != 0) continue;
                if (d > 1) degree += freq[d];
                if (v / d != d && v / d > 1) degree += freq[v / d];
            }
            best = Math.max(best, degree);
        }
        long strength = best * 100000;
        System.out.println((rate * duration >= strength ? 1 : 0) + " " + strength);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var rate, duration int64
	var n int
	fmt.Fscan(in, &rate, &duration, &n)
	keys := make([]int, n)
	for i := range keys {
		fmt.Fscan(in, &keys[i])
	}
	freq := make([]int64, slices.Max(keys)+1)
	for _, x := range keys {
		freq[x]++
	}
	// Divisibility of a key = sum of freq[d] over its divisors d > 1.
	var best int64
	for _, v := range keys {
		var degree int64
		for d := 1; d*d <= v; d++ {
			if v%d != 0 {
				continue
			}
			if d > 1 {
				degree += freq[d]
			}
			if v/d != d && v/d > 1 {
				degree += freq[v/d]
			}
		}
		best = max(best, degree)
	}
	strength := best * 100000
	broken := 0
	if rate*duration >= strength {
		broken = 1
	}
	fmt.Println(broken, strength)
}
